BEGIN TRANSACTION;
CREATE TABLE applicant_risk_factors (
	applicant_id VARCHAR, 
	risk_factor_id VARCHAR, 
	FOREIGN KEY(applicant_id) REFERENCES applicants (id), 
	FOREIGN KEY(risk_factor_id) REFERENCES risk_factors (id)
);
CREATE TABLE applicants (
	id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	age INTEGER, 
	income FLOAT, 
	location VARCHAR, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE coverage_options (
	id VARCHAR NOT NULL, 
	product_id VARCHAR, 
	name VARCHAR, 
	coverage_limit FLOAT, 
	additional_rate FLOAT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);
CREATE TABLE endorsements (
	id VARCHAR NOT NULL, 
	policy_id VARCHAR, 
	change_type VARCHAR, 
	old_value FLOAT, 
	new_value FLOAT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(policy_id) REFERENCES policies (id)
);
CREATE TABLE insured_assets (
	id VARCHAR NOT NULL, 
	applicant_id VARCHAR, 
	asset_type VARCHAR, 
	asset_value FLOAT, 
	location VARCHAR, 
	PRIMARY KEY (id), 
	FOREIGN KEY(applicant_id) REFERENCES applicants (id)
);
CREATE TABLE policies (
	id VARCHAR NOT NULL, 
	quote_id VARCHAR, 
	applicant_id VARCHAR, 
	start_date DATE, 
	end_date DATE, 
	premium FLOAT, 
	status VARCHAR, 
	accepted BOOLEAN, 
	payment_received BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(quote_id) REFERENCES quotes (id), 
	FOREIGN KEY(applicant_id) REFERENCES applicants (id)
);
CREATE TABLE policy_events (
	id INTEGER NOT NULL, 
	policy_id VARCHAR, 
	event_type VARCHAR, 
	previous_status VARCHAR, 
	new_status VARCHAR, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(policy_id) REFERENCES policies (id)
);
CREATE TABLE products (
	id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	product_line VARCHAR, 
	base_rate FLOAT, 
	min_age INTEGER, 
	max_age INTEGER, 
	max_coverage FLOAT, 
	active BOOLEAN, 
	PRIMARY KEY (id)
);
CREATE TABLE quotes (
	id VARCHAR NOT NULL, 
	applicant_id VARCHAR, 
	product_id VARCHAR, 
	asset_id VARCHAR, 
	coverage_amount FLOAT, 
	calculated_premium FLOAT, 
	status VARCHAR, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(applicant_id) REFERENCES applicants (id), 
	FOREIGN KEY(product_id) REFERENCES products (id), 
	FOREIGN KEY(asset_id) REFERENCES insured_assets (id)
);
CREATE TABLE renewals (
	id VARCHAR NOT NULL, 
	policy_id VARCHAR, 
	renewal_date DATE, 
	offered_premium FLOAT, 
	status VARCHAR, 
	PRIMARY KEY (id), 
	FOREIGN KEY(policy_id) REFERENCES policies (id)
);
CREATE TABLE risk_factors (
	id VARCHAR NOT NULL, 
	name VARCHAR, 
	factor_type VARCHAR, 
	multiplier FLOAT, 
	description TEXT, 
	PRIMARY KEY (id)
);
CREATE TABLE underwriting_decisions (
	id VARCHAR NOT NULL, 
	quote_id VARCHAR, 
	decision VARCHAR, 
	risk_score FLOAT, 
	reason TEXT, 
	reviewer VARCHAR, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(quote_id) REFERENCES quotes (id)
);
COMMIT;
